const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

const text = buffer.toString('utf8');

const parsed = JSON.parse(text);

// JSON 파일 하나에 기사 1개가 들어있는 경우
if (!Array.isArray(parsed)) {
  return [
    {
      json: parsed
    }
  ];
}

// JSON 파일 하나에 기사 여러 개가 배열로 들어있는 경우
return parsed.map(article => ({
  json: article
}));

return items.map(item => {
  const input = item.json;

  return {
    json: {
      article_id: input.article_id || '',
      title: input.title || '',
      content: input.content || '',
      images: Array.isArray(input.images) ? input.images : []
    }
  };
});

return items.map(item => {
  const raw = item.json.output[0].content[0].text;

  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const parsed = JSON.parse(cleaned);

  return {
    json: parsed
  };
});

return items.map(item => {
  const data = item.json;

  const keywordCandidates = (data.possible_keywords || []).map((item, index) => ({
    keyword_id: `K${index + 1}`,
    keyword: item.keyword || '',
    reason: item.reason || '',
    related_fact_ids: Array.isArray(item.related_fact_ids)
      ? item.related_fact_ids
      : []
  }));

  return {
    json: {
      ...data,
      keyword_candidates: keywordCandidates
    }
  };
});

return items.map(item => {
  const data = item.json;

  return {
    json: {
      article_id: data.article_id || '',

      article: {
        title: data.title || ''
      },

      analysis: {
        main_topic: data.main_topic || '',
        summary: data.summary || '',
        story_flow: Array.isArray(data.story_flow)
          ? data.story_flow
          : []
      },

      facts: Array.isArray(data.facts)
        ? data.facts
        : [],

      notable_quotes: Array.isArray(data.notable_quotes)
        ? data.notable_quotes
        : [],

      human_impact_cases: Array.isArray(data.human_impact_cases)
        ? data.human_impact_cases
        : [],

      important_numbers: Array.isArray(data.important_numbers)
        ? data.important_numbers
        : [],

      keyword_candidates: Array.isArray(data.keyword_candidates)
        ? data.keyword_candidates
        : [],

      ui_state: {
        ready_for_keyword_selection: true,
        ready_for_platform_selection: true,
        ready_for_requirements_input: true
      }
    }
  };
});
